import sys

sys.setrecursionlimit(10000)
s = sys.stdin.read().split()[0]

def parse(i):
    out = ''
    while i < len(s) and s[i] != ']':
        if s[i].isdigit():
            j = i
            while j < len(s) and s[j].isdigit():
                j += 1
            if j < len(s) and s[j] == '[':
                inner, k = parse(j + 1)
                out += inner * int(s[i:j])
                i = k + 1
            else:
                out += s[i:j]
                i = j
        else:
            out += s[i]
            i += 1
    return out, i

