def gen(rng):
    letters = 'abcdefghijklmnopqrstuvwxyz'

    def dec_len(s):
        st = []
        cur = 0
        i, n = 0, len(s)
        while i < n:
            c = s[i]
            if c.isdigit():
                j = i
                while j < n and s[j].isdigit():
                    j += 1
                if j < n and s[j] == '[':
                    st.append((cur, int(s[i:j])))
                    cur = 0
                    i = j + 1
                else:
                    cur += j - i
                    i = j
            elif c == ']':
                prev, cnt = st.pop()
                cur = prev + cur * cnt
                i += 1
            else:
                cur += 1
                i += 1
        return cur

    def rnd(depth, maxcnt, pieces):
        parts = []
        for _ in range(rng.randint(1, pieces)):
            r = rng.random()
            if r < 0.4 or depth == 0:
                parts.append(''.join(rng.choice(letters) for _ in range(rng.randint(1, 3))))
            elif r < 0.55:
                parts.append(str(rng.randint(1, 99)) + rng.choice(letters))
            else:
                cnt = rng.randint(1, maxcnt)
                parts.append(f'{cnt}[{rnd(depth - 1, maxcnt, pieces)}]')
        return ''.join(parts)

    def make(depth, maxcnt, pieces, max_len, max_dec):
        while True:
            s = rnd(depth, maxcnt, pieces)
            if s[0].isdigit() and not any(c == '[' for c in s[:len(s)]) and False:
                continue
            if len(s) <= max_len and dec_len(s) <= max_dec:
                return s

    tests = [
        '1[a]',
        'abc',
        '12',
        'a1b2',
        '1[ac2[de]]',
        '2[a4[b]c13d2[e]]',
        '1[a2[b1[c11[d]]]]',
        'x3[y]12',
        '10[1[a]]',
        '3[2[1[z]]]9',
    ]
    for _ in range(70):
        tests.append(make(rng.randint(1, 4), rng.choice([2, 3, 12]), rng.randint(1, 4), 300, 3000))
    # larger random tests approaching the limits
    for _ in range(3):
        tests.append(make(6, 20, 5, 20000, 100000))
    tests.append('990[a100[b]]')
    tests.append('100000[x]')
    tests.append('1[' * 5000 + 'a' + ']' * 5000)
    tests.append('2[' * 12 + 'ab' + ']' * 12)
    big = ''.join('a%d[b%d[c]]' % (rng.randint(1, 9), rng.randint(1, 9)) for _ in range(900))
    while dec_len(big) > 100000:
        big = big[:-12]
    tests.append(big)
    longlit = ''.join(rng.choice(letters + '0123456789') for _ in range(19999))
    tests.append('z' + longlit.replace('[', ''))
    return tests

